-- Read-only catalog capture for #5610 and the shared #5747 asset inventory.
-- Verify the connected target immediately before submitting. Preserve full output.
-- Statement deallocation does not reset index counters. Never reset statistics.
select now() as observed_at, pg_postmaster_start_time() as postmaster_started_at, (select stats_reset from pg_stat_database where datname=current_database()) as database_stats_reset, jsonb_agg(jsonb_build_object('schema',s.schemaname,'table',s.relname,'index',s.indexrelname,'index_oid',s.indexrelid::text,'table_oid',s.relid::text,'bytes',pg_relation_size(s.indexrelid),'scans',s.idx_scan,'last_scan',s.last_idx_scan,'definition',pg_get_indexdef(s.indexrelid),'valid',i.indisvalid,'ready',i.indisready,'unique',i.indisunique,'primary',i.indisprimary) order by s.schemaname,s.indexrelname) as indexes from pg_stat_user_indexes s join pg_index i using(indexrelid) where s.relid='public.assets'::regclass or s.indexrelname in ('idx_sgf_directory_path_trgm','idx_style_guide_files_tag_search_trgm','idx_style_guide_file_tags_tag_status','dam_search_embedding_claim_idx','idx_dam_search_documents_embedding_hnsw','idx_sg_search_documents_embedding_hnsw','dam_asset_image_vectors_vec_siglip_hnsw','dam_asset_image_vectors_vec_dino_hnsw','hts_rag_rulings_search_trgm_idx','hts_rag_ruling_sentences_hash_idx');
